-- ============================================================
-- Migration 026: Seed Nigerian Institutions (Complete Edition)
--
-- Covers all NUC-accredited universities (federal, state, private),
-- NBTE polytechnics, and NCCE colleges of education.
--
-- Safe to run multiple times — uses ON CONFLICT DO UPDATE.
-- If an institution is not in this list it will NOT throw an error,
-- it simply won't be inserted/updated.
-- ============================================================

BEGIN;

-- ──────────────────────────────────────────────────────────────
-- 1) Ensure unique index exists
-- ──────────────────────────────────────────────────────────────
CREATE UNIQUE INDEX IF NOT EXISTS idx_seed_institutions_name_country_unique
