ON CONFLICT ((LOWER(name)), country_code) DO UPDATE SET
  short_name   = EXCLUDED.short_name,
  aliases      = EXCLUDED.aliases,
  state        = EXCLUDED.state,
  city         = EXCLUDED.city,
  type         = EXCLUDED.type,
  ownership    = EXCLUDED.ownership,
  website      = EXCLUDED.website,
  email_domain = EXCLUDED.email_domain,
  source       = EXCLUDED.source,
  updated_at   = NOW();

-- ──────────────────────────────────────────────────────────────
-- 3) Verification — counts only, no errors if rows are missing
-- ──────────────────────────────────────────────────────────────
DO $$
DECLARE
  total_count  INTEGER;
  fed_uni      INTEGER;
  state_uni    INTEGER;
  priv_uni     INTEGER;
  poly_count   INTEGER;
  coe_count    INTEGER;
BEGIN
  SELECT COUNT(*) INTO total_count FROM public.seed_institutions WHERE country_code = 'NG';
  SELECT COUNT(*) INTO fed_uni     FROM public.seed_institutions WHERE country_code = 'NG' AND type = 'university'           AND ownership = 'federal';
  SELECT COUNT(*) INTO state_uni   FROM public.seed_institutions WHERE country_code = 'NG' AND type = 'university'           AND ownership = 'state';
  SELECT COUNT(*) INTO priv_uni    FROM public.seed_institutions WHERE country_code = 'NG' AND type = 'university'           AND ownership = 'private';
  SELECT COUNT(*) INTO poly_count  FROM public.seed_institutions WHERE country_code = 'NG' AND type = 'polytechnic';
  SELECT COUNT(*) INTO coe_count   FROM public.seed_institutions WHERE country_code = 'NG' AND type = 'college_of_education';

  RAISE NOTICE '========================================';
  RAISE NOTICE 'Migration 026 complete.';
  RAISE NOTICE '  Total NG institutions : %', total_count;
  RAISE NOTICE '  Federal universities  : %', fed_uni;
  RAISE NOTICE '  State universities    : %', state_uni;
  RAISE NOTICE '  Private universities  : %', priv_uni;
  RAISE NOTICE '  Polytechnics          : %', poly_count;
  RAISE NOTICE '  Colleges of Education : %', coe_count;
  RAISE NOTICE '========================================';
  RAISE NOTICE 'NOTE: Institutions not in this list are unaffected — no rows deleted.';
END $$;

COMMIT;